/// Step icons, drawn from the shared geometry in icon_paths.dart (generated by
/// tools/step_icons.py, which also draws docs/step_icons.svg).
///
/// Three forms:
/// - board badge ([StepIcon]): coloured circle, white sign, flat shadows
///   straight down;
/// - sign alone ([StepGlyph]): middle field and move list, in the step colour;
/// - card pill (move_detail.dart): white circle with the sign in the pill colour.
///
/// Overlapping signs (??, ?!, !?) cut the back sign along the front one
/// widened by a gap, so the gap is see-through and does not cover shadows.
library;

import 'dart:math' as math;

import 'package:flutter/material.dart';

import 'icon_paths.dart';

/// Icon kinds in display order (also the order of the icon sheet).
const iconKinds = [
  'brilliant',
  'only_move',
  'only_light',
  'best',
  'excellent',
  'good',
  'book',
  'forced',
  'neutral',
  'inaccuracy',
  'laxity',
  'pass',
  'mistake',
  'blunder',
  'mate',
];

/// Kind of the icon for a move: brilliant and only move override the step.
String iconKindOf(String step, String? subtype) {
  if (subtype == 'brilliant') return 'brilliant';
  if ((subtype == 'only_move' || subtype == 'only_light') && step == 'best') return subtype!;
  return step;
}

/// Icon colours: the same on light and dark boards.
Color markColor(String kind) => switch (kind) {
      'brilliant' => const Color(0xFF14A99C),
      'only_move' => const Color(0xFF3B7DD8),
      // лёгкий only — между best (зелёный) и only (синий)
      'only_light' => const Color(0xFF00A572),
      'best' => const Color(0xFF4CAF50),
      'excellent' => const Color(0xFF5C9E68),
      'good' => const Color(0xFF7FA486),
      'book' => const Color(0xFFB0702F),
      'forced' => const Color(0xFF5C626D),
      'neutral' => const Color(0xFF959595),
      'inaccuracy' => const Color(0xFFF0B414),
      'laxity' => const Color(0xFFF59B1E),
      'pass' => const Color(0xFF7E5BD0),
      'mistake' => const Color(0xFFE5622E),
      'blunder' => const Color(0xFFD7322F),
      'mate' => const Color(0xFF4CAF50),
      _ => const Color(0xFF959595),
    };

/// Kinds whose badge appears with a flash (the rest fade in).
bool flashesIn(String kind) =>
    kind == 'brilliant' || kind == 'only_move' || kind == 'only_light' || kind == 'best';

/// Kinds whose arrival makes the sign jump and sends an outline flying out.
bool isLoudKind(String kind) => kind == 'brilliant' || kind == 'blunder';

/// Kinds whose sign jumps on arrival: the loud ones and the tactical only
/// move (its sign jumps like brilliant's, without the outline).
bool jumpsIn(String kind) => isLoudKind(kind) || kind == 'only_move';

/// Board badge: coloured circle, white sign.
class StepIcon extends StatelessWidget {
  const StepIcon({
    super.key,
    required this.kind,
    this.size = 22,
    this.glyphScale = 1,
    this.glyphAngle = 0,
    this.brighten = 0,
    this.color,
    this.hand = clockHand,
  });

  final String kind;
  final double size;
  final Color? color;

  /// Angle of the clock hand (timeout), radians from twelve o'clock.
  final double hand;

  /// Sign rotation (resign flag waving, timeout clock turning).
  final double glyphAngle;

  /// Sign scale inside the badge (the jump animation).
  final double glyphScale;

  /// 0..1: how much the badge is lightened toward white (the appear flash).
  final double brighten;

  @override
  Widget build(BuildContext context) => CustomPaint(
        size: Size.square(size),
        painter: _BadgePainter(kind, color ?? markColor(kind),
            glyphScale: glyphScale, glyphAngle: glyphAngle, brighten: brighten, hand: hand),
      );
}

/// The sign alone, in [color] (middle field, move list, card pill).
class StepGlyph extends StatelessWidget {
  const StepGlyph(
      {super.key, required this.kind, required this.color, this.size = 14, this.shadow = true, this.hollow = false});

  /// The sign drawn as an outline (a hollow sign).
  final bool hollow;

  final String kind;
  final Color color;
  final double size;
  final bool shadow;

  @override
  Widget build(BuildContext context) => CustomPaint(
        size: Size.square(size),
        painter: _GlyphPainter(kind, color, shadow: shadow, hollow: hollow),
      );
}

class _BadgePainter extends CustomPainter {
  _BadgePainter(this.kind, this.c, {this.glyphScale = 1, this.glyphAngle = 0, this.brighten = 0, this.hand = clockHand});

  final String kind;
  final Color c;
  final double glyphScale;
  final double glyphAngle;
  final double brighten;
  final double hand;

  @override
  void paint(Canvas canvas, Size size) {
    final d = size.shortestSide;
    final center = size.center(Offset.zero);
    // плоская тень вниз
    canvas.drawCircle(center + Offset(0, d * 0.035), d / 2, Paint()..color = const Color(0x38000000));
    canvas.drawCircle(center, d / 2, Paint()..color = Color.lerp(c, Colors.white, brighten)!);
    canvas.save();
    canvas.translate(center.dx, center.dy);
    canvas.scale(glyphScale);
    canvas.rotate(glyphAngle);
    canvas.save();
    canvas.translate(0, d * 0.035);
    drawStepGlyph(canvas, kind, d * 0.78, Color.lerp(c, Colors.black, 0.28)!, hand: hand);
    canvas.restore();
    drawStepGlyph(canvas, kind, d * 0.78, Colors.white, hand: hand);
    canvas.restore();
  }

  @override
  bool shouldRepaint(_BadgePainter old) =>
      old.kind != kind || old.c != c || old.glyphScale != glyphScale || old.glyphAngle != glyphAngle ||
      old.brighten != brighten || old.hand != hand;
}

class _GlyphPainter extends CustomPainter {
  _GlyphPainter(this.kind, this.color, {required this.shadow, this.hollow = false});

  final String kind;
  final Color color;
  final bool shadow;
  final bool hollow;

  @override
  void paint(Canvas canvas, Size size) {
    final d = size.shortestSide;
    canvas.save();
    canvas.translate(size.width / 2, size.height / 2);
    if (shadow) {
      canvas.save();
      canvas.translate(0, d * 0.05);
      drawStepGlyph(canvas, kind, d, const Color(0x40000000));
      canvas.restore();
    }
    drawStepGlyph(canvas, kind, d, color, hollow: hollow);
    canvas.restore();
  }

  @override
  bool shouldRepaint(_GlyphPainter old) =>
      old.kind != kind || old.color != color || old.shadow != shadow || old.hollow != hollow;
}

final _cache = <String, Path>{};
Path _path(String d) => _cache.putIfAbsent(d, () => parseSvgPath(d));

/// Draws the sign of [kind] centred at the origin in a [size] box.
/// Resting angle of the clock hand (a little past twelve).
const clockHand = 0.7;

/// The timeout clock: dial, button on top and a hand at [hand] radians from
/// twelve o'clock (it turns in the badge animation).
void _drawClock(Canvas canvas, double size, Color color, double hand) {
  final r = size * 0.32;
  final c = Offset(0, size * 0.06);
  final stroke = Paint()
    ..color = color
    ..style = PaintingStyle.stroke
    ..strokeWidth = size * 0.11
    ..strokeCap = StrokeCap.round;
  canvas.drawCircle(c, r, stroke);
  canvas.drawLine(c + Offset(-size * 0.09, -r - size * 0.13), c + Offset(size * 0.09, -r - size * 0.13), stroke);
  canvas.drawLine(c, c + Offset(math.sin(hand), -math.cos(hand)) * (r * 0.62), stroke..strokeWidth = size * 0.09);
}

/// The draw: ½.
void _drawHalf(Canvas canvas, double size, Color color) {
  final tp = TextPainter(
    text: TextSpan(
        text: '½', style: TextStyle(fontSize: size * 0.95, height: 1, fontWeight: FontWeight.w900, color: color)),
    textDirection: TextDirection.ltr,
  )..layout();
  tp.paint(canvas, Offset(-tp.width / 2, -tp.height / 2));
}

void drawStepGlyph(Canvas canvas, String kind, double size, Color color,
    {double hand = clockHand, bool hollow = false}) {
  if (kind == 'timeout') return _drawClock(canvas, size, color, hand);
  if (kind == 'draw') return _drawHalf(canvas, size, color);
  // полый знак: только контур, чуть толще, чтобы не терялся
  final fill = hollow
      ? (Paint()
        ..color = color
        ..style = PaintingStyle.stroke
        ..strokeWidth = size * 0.09
        ..strokeJoin = StrokeJoin.round)
      : (Paint()..color = color);
  final sign = signs[kind == 'only_light' ? 'only_move' : kind];
  if (sign != null) {
    _drawSign(canvas, sign, size * signHeight[sign]!, fill);
    return;
  }
  final icon = icon24Layout[kind];
  if (icon != null) {
    final s = size / 24 * icon.scale;
    canvas.save();
    canvas.scale(s);
    canvas.translate(-icon.cx + icon.dx, -icon.cy + icon.dy);
    canvas.drawPath(_path(icon.path), fill);
    canvas.restore();
    return;
  }
  final glyphIcon = switch (kind) {
    'resign' => Icons.flag_rounded,
    'timeout' => Icons.timer_rounded,
    'branch' => Icons.call_split_rounded,
    _ => null,
  };
  if (glyphIcon != null) {
    final tp = TextPainter(
      text: TextSpan(
        text: String.fromCharCode(glyphIcon.codePoint),
        style: TextStyle(fontFamily: glyphIcon.fontFamily, fontSize: size * 0.8, height: 1, color: color),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, Offset(-tp.width / 2, -tp.height / 2));
    return;
  }
  if (kind == 'pass') {
    final w = 0.15 * size * 0.85;
    final stroke = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = w
      ..strokeCap = StrokeCap.round;
    canvas.drawCircle(Offset.zero, 0.29 * size, stroke);
    canvas.drawLine(Offset(-0.2 * size, 0.2 * size), Offset(0.2 * size, -0.2 * size), stroke);
  }
}

void _drawSign(Canvas canvas, String sign, double h, Paint fill) {
  (double, double, double, double) box(String ch) {
    final b = ch == '?' ? questionBox : bangBox;
    return (b.$1.toDouble(), b.$2.toDouble(), b.$3.toDouble(), b.$4.toDouble());
  }

  final chars = sign.split('');
  final widths = [
    for (final ch in chars)
      (box(ch).$3 - box(ch).$1) / (box(ch).$4 - box(ch).$2) * h,
  ];
  final spacing = (signSpacing[sign] ?? 0.12) * h;
  final total = widths.reduce((a, b) => a + b) + spacing * (chars.length - 1);
  var x = -total / 2 + (signShift[sign] ?? 0) * h;
  final placed = <(Path, Matrix4)>[];
  for (final (i, ch) in chars.indexed) {
    final b = box(ch);
    final s = h / (b.$4 - b.$2);
    final m = Matrix4.identity()
      ..translateByDouble(x, -h / 2, 0, 1)
      ..scaleByDouble(s, s, 1, 1)
      ..translateByDouble(-b.$1, -b.$2, 0, 1);
    // в паре с «?» верх «!» чуть срезан, иначе он кажется выше
    final bang = sign == '?!' || sign == '!?' ? bangPairPath : bangPath;
    placed.add((_path(ch == '?' ? questionPath : bang).transform(m.storage), m));
    x += widths[i] + spacing;
  }
  final overlap = sign == '??'; // ?! и !? стоят раздельно
  if (!overlap) {
    for (final (p, _) in placed) {
      canvas.drawPath(p, fill);
    }
    return;
  }
  // сверху — вопросительный знак (у ?? — правый)
  final ordered = sign == '?!' ? placed.reversed.toList() : placed;
  final back = ordered[0].$1, front = ordered[1].$1;
  final bounds = back.getBounds().expandToInclude(front.getBounds()).inflate(h);
  canvas.saveLayer(bounds, Paint());
  canvas.drawPath(back, fill);
  canvas.drawPath(
    front,
    Paint()
      ..blendMode = BlendMode.clear
      ..style = PaintingStyle.stroke
      ..strokeWidth = signGap * h
      ..strokeJoin = StrokeJoin.round,
  );
  canvas.drawPath(front, Paint()..blendMode = BlendMode.clear);
  canvas.restore();
  canvas.drawPath(front, fill);
}

/// Minimal SVG path parser: absolute M, L, H, V, C, Q, Z (the commands the
/// generator writes), implicit repeats included.
Path parseSvgPath(String d) {
  final path = Path();
  final tokens = RegExp(r'[MLHVCQZmlhvcqz]|-?\d*\.?\d+(?:e-?\d+)?').allMatches(d).map((m) => m.group(0)!).toList();
  var i = 0;
  var cmd = 'M';
  var cx = 0.0, cy = 0.0;
  double num() => double.parse(tokens[i++]);
  while (i < tokens.length) {
    final t = tokens[i];
    if (RegExp(r'^[A-Za-z]$').hasMatch(t)) {
      cmd = t;
      i++;
      if (cmd == 'Z' || cmd == 'z') {
        path.close();
        continue;
      }
    }
    switch (cmd) {
      case 'M':
        cx = num();
        cy = num();
        path.moveTo(cx, cy);
        cmd = 'L'; // следующие пары — неявные L
      case 'L':
        cx = num();
        cy = num();
        path.lineTo(cx, cy);
      case 'H':
        cx = num();
        path.lineTo(cx, cy);
      case 'V':
        cy = num();
        path.lineTo(cx, cy);
      case 'C':
        final x1 = num(), y1 = num(), x2 = num(), y2 = num();
        cx = num();
        cy = num();
        path.cubicTo(x1, y1, x2, y2, cx, cy);
      case 'Q':
        final x1 = num(), y1 = num();
        cx = num();
        cy = num();
        path.quadraticBezierTo(x1, y1, cx, cy);
      default:
        throw FormatException('Unsupported path command $cmd');
    }
  }
  return path;
}
